CREATE TABLE attendance_notifications (id VARCHAR(64) PRIMARY KEY,entry_id VARCHAR(36) NOT NULL,recipient_id VARCHAR(36) NOT NULL,email VARCHAR(254) NOT NULL,payload JSON NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,first_attempt_at VARCHAR(32),created_at VARCHAR(32) NOT NULL,sent_at VARCHAR(32),read_at VARCHAR(32),last_error VARCHAR(80) NOT NULL DEFAULT '',INDEX attendance_notification_status(status,created_at));
